import {MOTION_TYPES,MOTION_PROPERTIES,MOTION_VALUES} from './motion-schema.js';
import {walk,isElement,localName} from './model.js';
import {propertyGroups} from './registry.js';
import {bindingPaths} from './design-data.js';
export const PROPERTY_VALUES={HorizontalAlignment:['Stretch','Left','Center','Right'],VerticalAlignment:['Stretch','Top','Center','Bottom'],Orientation:['Vertical','Horizontal'],Visibility:['Visible','Hidden','Collapsed'],IsVisible:['True','False'],IsEnabled:['True','False'],IsChecked:['True','False'],IsReadOnly:['True','False'],LastChildFill:['True','False'],ClipToBounds:['True','False'],TextWrapping:['NoWrap','Wrap'],TextAlignment:['Left','Center','Right','Justify'],FontWeight:['Normal','Medium','SemiBold','Bold','Light'],FontStyle:['Normal','Italic','Oblique'],'DockPanel.Dock':['Left','Top','Right','Bottom'],Stretch:['None','Fill','Uniform','UniformToFill'],Mode:['Default','OneWay','TwoWay','OneTime','OneWayToSource'],UpdateSourceTrigger:['Default','PropertyChanged','LostFocus','Explicit']};
const descriptions={Width:'Explicit layout width in device-independent pixels or Auto.',Height:'Explicit layout height in device-independent pixels or Auto.',Margin:'Outer spacing: uniform, horizontal/vertical, or left,top,right,bottom.',Padding:'Inner content spacing.',DataContext:'Inherited source object for child bindings.',ItemsSource:'Collection used to create items and template instances.',Template:'ControlTemplate that defines a control’s visual tree.','Grid.Row':'Zero-based row index in the containing Grid.','Grid.Column':'Zero-based column index in the containing Grid.','Grid.RowSpan':'Number of grid rows occupied by the control.','Grid.ColumnSpan':'Number of grid columns occupied by the control.'};
export function openTags(source){const stack=[];const tokens=source.matchAll(/<!--[\s\S]*?-->|<\/?([\w:.-]+)(?:[^>"']|"[^"]*"|'[^']*')*>/g);for(const m of tokens){if(m[0].startsWith('<!--'))continue;if(m[0].startsWith('</')){const i=stack.lastIndexOf(m[1]);if(i>=0)stack.splice(i);}else if(!m[0].endsWith('/>'))stack.push(m[1]);}return stack;}
export function completionContext(source){let start=-1,quote=null;for(let i=0;i<source.length;i++){if(quote){if(source[i]===quote)quote=null;continue;}if(source.startsWith('<!--',i)||source.startsWith('<![CDATA[',i)||source.startsWith('<?',i)){const close=source.startsWith('<!--',i)?'-->':source.startsWith('<?',i)?'?>':']]>',end=source.indexOf(close,i+2);if(end<0)return {start:-1,blocked:true};i=end+close.length-1;start=-1;continue;}if(source[i]==='<')start=i;else if(start>=0&&(source[i]==='"'||source[i]==="'"))quote=source[i];else if(source[i]==='>')start=-1;}return {start,quote,blocked:false};}
export function completeXaml(source,offset,{registry,document,context={}}){const before=source.slice(0,offset),scan=completionContext(before),last=scan.start,tail=last<0?'':before.slice(last),resources=[],names=[];if(scan.blocked)return [];if(document?.root)walk(document.root,n=>{if(isElement(n)){if(n.props['x:Key'])resources.push(n.props['x:Key']);if(n.props['x:Name']||n.props.Name)names.push(n.props['x:Name']||n.props.Name);}});const token=before.match(/[\w:.$[\]-]*$/)?.[0]||'';const result=(values,kind,start=offset-token.length,transform=v=>v)=>[...new Map(values.map(v=>{const obj=typeof v==='string'?{label:v}:v;return [obj.label,obj];})).values()].filter(v=>v.label.toLowerCase().startsWith(source.slice(start,offset).toLowerCase())).map(v=>({label:v.label,detail:v.detail||kind,start,end:offset,insertText:transform(v.label),caretOffset:undefined,...v}));
  const quoted=tail.match(/([\w:.-]+)\s*=\s*(?:"([^"]*)|'([^']*))$/);
  if(quoted){const property=quoted[1],value=quoted[2]??quoted[3],valueStart=offset-value.length;
    if(/\{(?:StaticResource|DynamicResource)\s+[^}]*$/.test(value))return result(resources,'Resource key');
    if(/\{Binding(?:\s+Path=|\s+)?[^,}]*$/.test(value)){const path=value.replace(/^.*\{Binding\s*(?:Path=)?/,'');return result(bindingPaths(context),'Data binding path',offset-path.length);}
    if(/ElementName\s*=\s*\w*$/.test(value))return result(names,'Named element');
    if(/\b(Mode|UpdateSourceTrigger)\s*=\s*\w*$/.test(value)){const key=value.match(/\b(Mode|UpdateSourceTrigger)\s*=/)[1];return result(PROPERTY_VALUES[key],key);}
    if(value.startsWith('{')&&!value.includes(' '))return result(['Binding','StaticResource','DynamicResource','TemplateBinding','RelativeSource','x:Null'],'Markup extension',valueStart+1);
    const tag=tail.match(/^<([\w:.-]+)/)?.[1];const descriptor=registry.get(tag||'');const meta=descriptor?.properties?.find(p=>typeof p==='object'&&p.name===property);let values=meta?.values||PROPERTY_VALUES[property]||MOTION_VALUES[property]||[];
    if(property==='Storyboard.TargetName'||property==='SourceName')values=names;
    if(property==='Storyboard.TargetProperty')values=['Opacity','Width','Height','Canvas.Left','Canvas.Top','(UIElement.RenderTransform).(RotateTransform.Angle)','(Control.Background).(SolidColorBrush.Color)'];
    if(['Background','Foreground','BorderBrush','Fill','Stroke'].includes(property))values=['Transparent','White','Black','#7953E8',...resources.map(k=>`{StaticResource ${k}}`)];
    if(['Text','Content','DataContext','ItemsSource','Command'].includes(property)&&!value.startsWith('{'))values=['{Binding }',...resources.map(k=>`{StaticResource ${k}}`)];
    if(['Grid.Row','Grid.Column','Grid.RowSpan','Grid.ColumnSpan'].includes(property))values=Array.from({length:12},(_,i)=>String(i+(property.endsWith('Span')?1:0)));
    if(['Width','Height'].includes(property))values=['Auto','100','240','320','480'];
    return result(values,'Property value',valueStart);
  }
  if(/<\/[\w:.-]*$/.test(before))return result(openTags(before.slice(0,last)).reverse(),'Closing element');
  if(/<[\w:.-]*$/.test(before))return result([...MOTION_TYPES,...registry.list().map(c=>({label:c.type,detail:c.description||`${c.category} control`})),...['Grid.RowDefinitions','Grid.ColumnDefinitions','RowDefinition','ColumnDefinition','ControlTemplate','DataTemplate','Style','Setter','ResourceDictionary','SolidColorBrush','Run','Span','Bold','Italic','LineBreak']],'Element');
  if(last>=0&&!scan.quote){const tag=tail.match(/^<([\w:.-]+)/)?.[1],descriptor=registry.get(tag||''),existing=new Set([...tail.matchAll(/([\w:.-]+)\s*=/g)].map(m=>m[1]));let props=[...new Set([...Object.values(propertyGroups).flat(),...MOTION_PROPERTIES,'x:Name','x:Key','Orientation','LastChildFill','Rows','Columns','RowDefinitions','ColumnDefinitions','Color','TargetType','Property','Value',...(descriptor?.properties||[]).map(p=>typeof p==='string'?p:p.name)])].filter(p=>!existing.has(p));return result(props.map(label=>({label,detail:descriptions[label]||`${tag||'Element'}.${label}`,caretOffset:label.length+2})),'Property',offset-token.length,v=>v+'=""');}
  return [];
}
